import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Attempting to Improve Discard Performance | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Attempting to Improve Discard Performance | Ceph Days NYC 2024","date":"2024-06-18T00:00:00.000Z","updated":"2024-06-19T00:00:00.000Z","tags":["Ceph","性能优化","RBD","固件更新","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024.md"};function o(s,a,n,p,_,h){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph Days NYC 2024会议聚焦于Ceph分布式存储系统中，尤其是在RBD（RADOS Block Device）工作负载下，遇到的性能问题。会议深入探讨了问题的发现、分析过程、解决方案以及未来的改进方向。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ol><li><p><strong>问题发现</strong>：</p><ul><li>在特定驱动器模型中，当驱动器大量写入并开始覆盖旧数据时，性能突然下降。</li><li>该问题在驱动器满载且未发送丢弃命令（discards）时尤为明显。</li></ul></li><li><p><strong>初步解决方案</strong>：</p><ul><li>在部分驱动模型上启用异步丢弃命令，对性能有显著提升，但对其他模型影响不大。</li><li>与驱动器供应商合作，获取新的固件更新以解决性能问题。</li></ul></li><li><p><strong>固件更新效果</strong>：</p><ul><li>新固件使丢弃命令的执行速度提升近一倍，但仍远低于参考模型。</li></ul></li><li><p><strong>内部改进尝试</strong>：</p><ul><li>增加丢弃线程池以提高丢弃命令的并行处理能力，但效果不明显。</li><li>发现驱动器固件可能以单线程方式处理丢弃命令，限制了并行处理的潜力。</li></ul></li><li><p><strong>其他潜在改进</strong>：</p><ul><li>研究不同的分配器（allocator）对性能的影响，特别是针对混合分配器和AVL分配器的比较。</li><li>需要进一步测试以确定不同分配器对不同类型驱动器的影响。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续与供应商合作，优化固件以进一步提升性能。</li><li>进一步研究并测试不同的分配器，以找到最适合当前存储环境的配置。</li><li>继续在社区中分享和讨论改进方案，以获取更多反馈和建议。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和分析启用丢弃命令后的性能数据。</li><li>与社区合作，推动并优化丢弃命令的多线程支持。</li><li>定期回顾和评估分配器的性能，确保最佳配置。</li></ul><h4 id="总结与反思" tabindex="-1">总结与反思 <a class="header-anchor" href="#总结与反思" aria-label="Permalink to &quot;总结与反思&quot;">​</a></h4><ul><li>通过深入分析和社区合作，团队成功找到了初步解决方案。</li><li>开源产品Ceph的优势在于能够快速响应问题，并与社区共同进步。</li><li>对社区的贡献不仅帮助了自身，也促进了整个社区的发展和成熟。</li></ul><h4 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h4><ul><li>对Ceph社区的支持和帮助表示感谢，并鼓励团队成员继续积极参与社区贡献。</li></ul><p>本次会议记录涵盖了问题的发现、分析、解决方案及未来展望，为后续的工作提供了明确的方向和行动计划。</p>',14)])])}const u=e(r,[["render",o]]);export{c as __pageData,u as default};
